import sys

def can_form_matrix(matrix, n):
    for i in range(n):
        for j in range(n):
            if matrix[i][j] == 1:
                if any(matrix[x][j] == 1 for x in range(i)):
                    return False
                if any(matrix[i][y] == 1 for y in range(j)):
                    return False
    return True

input = sys.stdin.read().split()
t = int(input[0])
index = 1
results = []

for _ in range(t):
    n = int(input[index])
    matrix = [list(map(int, input[index + i + 1])) for i in range(n)]
    index += n + 1
    results.append("YES" if can_form_matrix(matrix, n) else "NO")

print("\n".join(results))
